"""Core AFL-style greybox fuzzing simulation."""

from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Dict, Iterable, Iterator, List, Optional, Sequence, Set, Tuple

import numpy as np

from fuzzsim.bitmap import CoverageBitmap
from fuzzsim.mutation import bit_flip, byte_flip, delete_bytes, insert_bytes, random_byte
from fuzzsim.program_model import ExecutionTrace, SimulatedProgram
from fuzzsim.seed import TestCase


INTERESTING_8 = [-128, -1, 0, 1, 16, 32, 64, 100, 127]
INTERESTING_16 = [-32768, -129, 128, 255, 256, 512, 1000, 1024, 4096, 32767]
INTERESTING_32 = [-2147483648, -100663046, -32769, 32768, 65535, 65536, 100663045, 2147483647]


@dataclass(frozen=True)
class MutationCandidate:
    """A deterministic mutation emitted by a fuzzing stage."""

    data: bytes
    stage: str
    offset: int = 0
    width: int = 1


@dataclass(frozen=True)
class CalibrationResult:
    """Summary of AFL's seed calibration phase."""

    stable: bool
    stable_edges: Set[int]
    unstable_edges: Set[int]
    stability: float
    average_exec_time: float
    runs: int


@dataclass(frozen=True)
class AFLRunResult:
    """Final metrics for a fuzzing campaign."""

    paths_discovered: int
    unique_crashes: int
    corpus_size: int
    edge_coverage: float
    execs: int
    favored_seeds: int
    bitmap_coverage: int


class ForkServerSimulator:
    """Small model of AFL's fork server startup amortization."""

    def __init__(
        self,
        program: SimulatedProgram,
        startup_cost: float = 0.003,
        exec_overhead: float = 0.0002,
        use_forkserver: bool = True,
    ):
        self.program = program
        self.startup_cost = startup_cost
        self.exec_overhead = exec_overhead
        self.use_forkserver = use_forkserver
        self.started = False
        self.total_execs = 0

    def execute_once(self, data: bytes) -> ExecutionTrace:
        trace = self.program.trace(data)
        extra = self.exec_overhead
        if not self.use_forkserver or not self.started:
            extra += self.startup_cost
        self.started = True
        self.total_execs += 1
        return replace(trace, exec_time=trace.exec_time + extra)


class CrashDeduplicator:
    """Coverage-hash based crash deduplication."""

    def __init__(self):
        self.coverage_bitmap = CoverageBitmap()
        self.unique_crashes: Dict[str, TestCase] = {}

    def crash_hash(self, trace: ExecutionTrace) -> str:
        return self.coverage_bitmap.trace_hash(trace.bitmap_counts)

    def is_unique(self, trace: ExecutionTrace) -> bool:
        if not trace.is_crash:
            return False
        return self.crash_hash(trace) not in self.unique_crashes

    def record(self, testcase: TestCase):
        self.unique_crashes[testcase.metadata["crash_hash"]] = testcase


class AFLFuzzer:
    """A deterministic simulation of AFL's core fuzzing loop."""

    def __init__(
        self,
        program: SimulatedProgram,
        seed_inputs: Optional[Sequence[bytes]] = None,
        rng_seed: int = 42,
        user_dictionary: Optional[Iterable[bytes]] = None,
        calibration_runs: int = 3,
        max_input_size: int = 32,
    ):
        self.program = program
        self.bitmap = CoverageBitmap()
        self.edge_coverage: Set[int] = set()
        self.queue: List[TestCase] = []
        self.paths_seen: Set[Tuple[int, ...]] = set()
        self.path_frequencies: Dict[Tuple[int, ...], int] = {}
        self.crash_dedup = CrashDeduplicator()
        self.crashes: List[TestCase] = []
        self.rng = np.random.RandomState(rng_seed)
        self.forkserver = ForkServerSimulator(program)
        self.calibration_runs = calibration_runs
        self.iteration = 0
        self.max_input_size = max_input_size
        self.user_dictionary = sorted({bytes(token) for token in (user_dictionary or [])})
        self.auto_dictionary: Set[bytes] = set()

        for data in seed_inputs or []:
            self.add_to_queue(data=data, parent=None, source="seed", force=True)

    def _execute(self, data: bytes) -> ExecutionTrace:
        trace = self.forkserver.execute_once(data)
        self.paths_seen.add(trace.path_id)
        self.path_frequencies[trace.path_id] = self.path_frequencies.get(trace.path_id, 0) + 1
        return trace

    @staticmethod
    def _to_signed_bytes(value: int, width: int, endian: str) -> bytes:
        mask = (1 << (width * 8)) - 1
        return int(value & mask).to_bytes(width, endian, signed=False)

    @staticmethod
    def _overwrite_bytes(data: bytes, pos: int, token: bytes) -> bytes:
        buf = bytearray(data)
        if pos > len(buf):
            pos = len(buf)
        end = min(len(buf), pos + len(token))
        buf[pos:end] = token[:end - pos]
        if end - pos < len(token):
            buf.extend(token[end - pos:])
        return bytes(buf)

    def calibrate(self, data: bytes, runs: Optional[int] = None) -> CalibrationResult:
        """Run a testcase multiple times to estimate stability."""
        run_count = runs or self.calibration_runs
        traces = [self._execute(data) for _ in range(run_count)]
        coverage_sets = [set(trace.edge_ids) for trace in traces]
        stable_edges = set.intersection(*coverage_sets) if coverage_sets else set()
        union_edges = set.union(*coverage_sets) if coverage_sets else set()
        unstable_edges = union_edges - stable_edges
        stability = 1.0 if not union_edges else len(stable_edges) / len(union_edges)
        avg_exec_time = float(sum(trace.exec_time for trace in traces) / max(1, len(traces)))
        return CalibrationResult(
            stable=(len(unstable_edges) == 0),
            stable_edges=stable_edges,
            unstable_edges=unstable_edges,
            stability=stability,
            average_exec_time=avg_exec_time,
            runs=run_count,
        )

    def trim(self, data: bytes, target_trace: Optional[ExecutionTrace] = None) -> bytes:
        """Trim an input by removing power-of-two chunks while preserving coverage."""
        if len(data) <= 1:
            return data

        current = data
        trace = target_trace or self._execute(current)
        target_coverage = set(trace.edge_ids)
        remove_size = 1
        while remove_size * 2 < len(current):
            remove_size *= 2

        while remove_size >= 1 and len(current) > 1:
            pos = 0
            while pos < len(current):
                candidate = delete_bytes(current, pos, remove_size)
                candidate_trace = self._execute(candidate)
                if set(candidate_trace.edge_ids) == target_coverage:
                    current = candidate
                    trace = candidate_trace
                    continue
                pos += remove_size
            remove_size //= 2
        return current

