        bit_count = len(data) * 8
        for width in (1, 2, 4):
            if bit_count < width:
                continue
            for pos in range(bit_count - width + 1):
                yield MutationCandidate(bit_flip(data, pos, width), f"bitflip_{width}", pos, width)

    def generate_byteflip_mutations(self, data: bytes) -> Iterator[MutationCandidate]:
