    def _apply_havoc_stack(
        self,
        data: bytes,
        num_mutations: int,
        allowed_positions: Optional[Sequence[int]] = None,
    ) -> bytes:
        result = data
        safe_positions = list(allowed_positions) if allowed_positions is not None else None
        for _ in range(num_mutations):
            if len(result) == 0:
                result = b"\x00"
                safe_positions = [0]
